-- 000015_icd10_diagnosis_codes.up.sql
-- ICD-10 疾病诊断编码表 + 种子数据
-- 数据来源: ICD-10-CN (Chinese Version), 共 1586 条诊断编码
-- 用途: 诊断名称模糊搜索/自动补全

-- 诊断编码表
CREATE TABLE diagnosis_codes (
    id             BIGSERIAL PRIMARY KEY,
    code           VARCHAR(10)  NOT NULL,
    disease_name   VARCHAR(200) NOT NULL,
    chapter_code   VARCHAR(20),
    chapter_name   VARCHAR(100),
    category_code  VARCHAR(20),
    category_name  VARCHAR(100),
    py_code        VARCHAR(50),
    is_common      BOOLEAN NOT NULL DEFAULT FALSE,
    status         SMALLINT NOT NULL DEFAULT 1,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX idx_diagnosis_code ON diagnosis_codes (code);
CREATE INDEX idx_diagnosis_name ON diagnosis_codes (disease_name);
CREATE INDEX idx_diagnosis_py ON diagnosis_codes (py_code);
CREATE INDEX idx_diagnosis_chapter ON diagnosis_codes (chapter_code);

